/**
 * Generated by `createservice billing.ExportPaymentsService`
 */

const Big = require('big.js')
const dayjs = require('dayjs')
const get = require('lodash/get')

const conf = require('@open-condo/config')
const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { checkDvAndSender } = require('@open-condo/keystone/plugins/dvAndSender')
const { GQLCustomSchema } = require('@open-condo/keystone/schema')
const { extractReqLocale } = require('@open-condo/locales/extractReqLocale')
const { i18n } = require('@open-condo/locales/loader')

const access = require('@condo/domains/acquiring/access/ExportPaymentsService')
const { Payment } = require('@condo/domains/acquiring/utils/serverSchema')
const { DV_VERSION_MISMATCH, WRONG_FORMAT } = require('@condo/domains/common/constants/errors')
const { NOTHING_TO_EXPORT } = require('@condo/domains/common/constants/errors')
const { createExportFile } = require('@condo/domains/common/utils/createExportFile')
const { loadListByChunks } = require('@condo/domains/common/utils/serverSchema')
const { normalizeTimeZone } = require('@condo/domains/common/utils/timezone')
const { DEFAULT_ORGANIZATION_TIMEZONE } = require('@condo/domains/organization/constants/common')

const DATE_FORMAT = 'DD-MM-YYYY'
const TIME_FORMAT = 'HH-mm-ss'
const PAYMENT_FIELDS = 'id order amount implicitFee accountNumber depositedDate recipientBankAccount rawAddress frozenReceipt '
    + 'receipt { category { name } property { address } account { unitName } } '
    + 'invoice { number property { id address } unitName contact { property { id address } unitName } } '

const PAYMENT_EXPORT_HEADERS = [
    'date',
    'time',
    'accountNumber',
    'address',
    'amount',
    'fee',
    'recipientAmount',
    'paymentOrder',
    'bankAccount',
    'services',
]

const getPaymentExportHeaders = (locale) => PAYMENT_EXPORT_HEADERS.reduce((headers, header) => ({
    ...headers,
    [header]: i18n(`excelExport.headers.paymentsToEmail.${header}`, { locale }),
}), {})

const ERRORS = {
    DV_VERSION_MISMATCH: {
        // TODO(pahaz): mutation! cahnge
        query: 'exportPaymentsToExcel',
        variable: ['data', 'dv'],
        code: BAD_USER_INPUT,
        type: DV_VERSION_MISMATCH,
        message: 'Wrong value for data version number',
    },
    WRONG_SENDER_FORMAT: {
        // TODO(pahaz): mutation! cahnge
        query: 'exportPaymentsToExcel',
        variable: ['data', 'sender'],
        code: BAD_USER_INPUT,
        type: WRONG_FORMAT,
        message: 'Invalid format of "sender" field value. {details}',
        correctExample: '{ "dv": 1, "fingerprint": "uniq-device-or-container-id" }',
        messageInterpolation: { details: 'Please, check the example for details' },
    },
    NOTHING_TO_EXPORT: {
        // TODO(pahaz): mutation! cahnge
        query: 'exportPaymentsToExcel',
        code: BAD_USER_INPUT,
        type: NOTHING_TO_EXPORT,
        message: 'No payments found to export',
        messageForUser: 'api.acquiring.exportPaymentsToExcel.NOTHING_TO_EXPORT',
    },
}

const ExportPaymentsService = new GQLCustomSchema('ExportPaymentsService', {
    types: [
        {
            access: true,
            type: 'input ExportPaymentsToExcelInput { dv: Int!, sender: SenderFieldInput!, where: PaymentWhereInput!, sortBy: [SortPaymentsBy!], timeZone: String! }',
        },
        {
            access: true,
            type: 'type ExportPaymentsToExcelOutput { status: String!, linkToFile: String! }',
        },
    ],

    // TODO(pahaz): change to MUTATION!!!
    queries: [
        {
            access: access.canExportPaymentsToExcel,
            schema: 'exportPaymentsToExcel(data: ExportPaymentsToExcelInput!): ExportPaymentsToExcelOutput',
            resolver: async (parent, args, context) => {
                const { where, sortBy, timeZone: timeZoneFromUser } = args.data

                checkDvAndSender(args.data, ERRORS.DV_VERSION_MISMATCH, ERRORS.WRONG_SENDER_FORMAT, context)
                const locale = extractReqLocale(context.req) || conf.DEFAULT_LOCALE

                const timeZone = normalizeTimeZone(timeZoneFromUser) || DEFAULT_ORGANIZATION_TIMEZONE
                const formatDate = (date, format) => date ? dayjs(date).utc().tz(timeZone).format(format) : ''

                const objs = await loadListByChunks({
                    context,
                    list: Payment,
                    where,
                    sortBy,
                    fields: PAYMENT_FIELDS,
                })

                if (objs.length === 0) {
                    throw new GQLError(ERRORS.NOTHING_TO_EXPORT, context)
                }

                const excelRows = objs.map(obj => {
                    const services = get(obj, ['frozenReceipt', 'data', 'services'], [])
                    const servicesNames = Array.isArray(services)
                        ? services.map(({ name }) => name).filter(Boolean).slice(0, 3)
                        : []
                    const categoryName = get(obj, ['receipt', 'category', 'name'], '')
                    const receiptAddress = obj.receipt?.property?.address || ''
                    const receiptUnitName = obj.receipt?.account?.unitName || ''
                    const invoiceProperty = obj.invoice?.property
                    const invoiceContact = obj.invoice?.contact
                    const invoiceAddress = invoiceProperty?.address || invoiceContact?.property?.address || ''
                    let invoiceUnitName = invoiceContact?.unitName || ''
                    if (invoiceProperty) {
                        invoiceUnitName = obj.invoice?.unitName || ''
                        if (!invoiceUnitName && invoiceProperty.id === invoiceContact?.property?.id) {
                            invoiceUnitName = invoiceContact?.unitName || ''
                        }
                    }
                    const paymentAddress = obj.rawAddress
                        || [receiptAddress, receiptUnitName].filter(Boolean).join(', ')
                        || [invoiceAddress, invoiceUnitName].filter(Boolean).join(', ')
                    const amount = Big(get(obj, 'amount', 0))
                    const implicitFee = Big(get(obj, 'implicitFee', 0) || 0)

                    return {
                        date: formatDate(obj.depositedDate, DATE_FORMAT),
                        time: formatDate(obj.depositedDate, TIME_FORMAT),
                        accountNumber: obj.invoice?.number ?? obj.accountNumber ?? '',
                        address: paymentAddress,
                        amount: amount.toFixed(2),
                        fee: implicitFee.toFixed(2),
                        recipientAmount: amount.minus(implicitFee).toFixed(2),
                        paymentOrder: get(obj, 'order', ''),
                        bankAccount: get(obj, 'recipientBankAccount', ''),
                        services: servicesNames.length ? servicesNames.join(', ') : categoryName,
                    }
                })

                const { url: linkToFile } = await createExportFile({
                    fileName: `payments_${dayjs().format('DD_MM')}.xlsx`,
                    templatePath: './domains/acquiring/templates/PaymentsExportTemplate.xlsx',
                    replaces: {
                        payments: excelRows,
                        i18n: getPaymentExportHeaders(locale),
                    },
                    meta: {
                        listkey: 'Payment',
                        id: objs[0].id,
                    },
                })

                return { status: 'ok', linkToFile }
            },
        },
    ],

})

module.exports = {
    ExportPaymentsService,
}
